using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class FogMotionDefinitionOperations:RefCounted
{
    private readonly ActorPropertyOperations _properties=new();private readonly ActorDefinitionOperations _definitions=new();private readonly ActorAnimationOperations _animation=new();
    private GArray Rows(string name)=>GD.Load<GDScript>("res://scripts/actors/fog/fog_motion_definition.gd").GetScriptConstantMap()[name].AsGodotArray();
    private Resource Property(Resource d,string key,string title,Variant value,bool keyed=false){var p=_properties.create(new StringName(key),title,value,keyed);d.Get("properties").AsGodotArray().Add(p);return p;}
    public void extend_actor(Resource d)
    {
        string type=d.Get("type_id").AsString();if(type is not ("fog_volume" or "global_fog")||_definitions.find_property(d,new StringName("fog_motion_mode"))!=null)return;bool global=type=="global_fog";var mode=Property(d,"fog_motion_mode","Movement",0);mode.Get("options").AsGodotDictionary().Merge(new Settings{["group"]="Motion & simulation",["choices"]=global?new GArray{"Static","Procedural"}:new GArray{"Static","Procedural","Simulated","Simulated + procedural detail"},["refresh_inspector"]=true,["no_keyframes"]=true});
        foreach(var item in Rows("MOTION_ROWS")){var row=item.AsGodotArray();string group=row[3].AsString();if(global&&group is not ("Wind" or "Turbulence" or "Procedural detail"))continue;var p=Property(d,row[0].AsString(),row[1].AsString(),row[2],true);var options=p.Get("options").AsGodotDictionary();options.Merge(row[4].AsGodotDictionary());options["group"]=group;options["visible_when"]=new Settings{["property"]="fog_motion_mode",["values"]=group is "Wind" or "Turbulence"?new GArray{1,2,3}:group=="Procedural detail"?new GArray{1,3}:new GArray{2,3}};}
        if(global)return;var links=Property(d,"fog_motion_links","Source attachment remapping",new Settings());links.Get("options").AsGodotDictionary().Merge(new Settings{["hidden"]=true,["no_keyframes"]=true,["group"]="Motion & simulation"});for(int i=0;i<4;i++)foreach(string kind in new[]{"source","velocity"}){var p=Property(d,$"fog_{kind}_{i}",(kind=="source"?"Emission source":"Velocity influence")+" "+(i+1),default);p.Set("object_type",new StringName(kind=="source"?"fog_emitter":"fog_velocity_field"));p.Get("options").AsGodotDictionary().Merge(new Settings{["group"]=kind=="source"?"Emission":"Velocity fields",["visible_when"]=new Settings{["property"]="fog_motion_mode",["values"]=new GArray{2,3}}});}Property(d,"fog_motion_status","Transport status",false).Get("options").AsGodotDictionary().Merge(new Settings{["group"]="Motion & simulation",["fog_motion_status"]=true,["no_keyframes"]=true});
    }
    private Resource Definition(string type,string title){var d=new ActorObjectDefinition();d.Set("type_id",new StringName(type));d.Set("display_name",title);return d;}
    public Resource emitter_definition(){var d=Definition("fog_emitter","Fog Emission Source");add_rows(d,Rows("EMITTER_ROWS"));var p=Property(d,"mesh","Closed source mesh","");p.Get("options").AsGodotDictionary().Merge(new Settings{["file_picker"]=true,["extensions"]=new GArray{"tres","res","mesh"},["native_resource_types"]=new GArray{"Mesh"},["file_resource_mode"]="uneditable",["group"]="Source",["visible_when"]=new Settings{["property"]="shape",["values"]=new GArray{5}}});return d;}
    public Resource velocity_definition(){var d=Definition("fog_velocity_field","Fog Velocity Influence");add_rows(d,Rows("VELOCITY_ROWS"));return d;}
    public void add_rows(Resource d,GArray rows){foreach(var item in rows){var row=item.AsGodotArray();var p=Property(d,row[0].AsString(),row[1].AsString(),row[2],true);var options=p.Get("options").AsGodotDictionary();options.Merge(row[3].AsGodotDictionary());options["group"]=d.Get("type_id").AsString()=="fog_emitter"?"Source":"Influence";}}
    public int resolution(Settings values){int index=Math.Clamp(values.GetValueOrDefault("fog_quality",0).AsInt32(),0,4);return index==4?Math.Clamp(values.GetValueOrDefault("fog_resolution",16).AsInt32(),4,32):new[]{8,12,16,24}[index];}
    public bool physical_path(string[] path){if(path.Length==0)return false;string key=path[0];return key is "position" or "rotation" or "scale" or "volume_size" or "shape" or "boundary_mesh" or "field" or "fog_motion_links"||key.StartsWith("fog_",StringComparison.Ordinal)&&key is not ("fog_presets" or "fog_motion_status");}
    public Variant content(Variant value,int depth)
    {
        if(depth>12)return "reference depth limit";if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Resource resource){if(ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_reference.gd")){var resolved=_animation.resolve_reference(resource);return content(resolved==null?default:Variant.From(resolved),depth+1);}if(ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_data.gd")){var result=new Settings{["type"]=resource.Get("type_id")};foreach(var entry in resource.Get("values").AsGodotDictionary()){string key=entry.Key.AsString();if(key.StartsWith("brush_",StringComparison.Ordinal)||key is "paint_tool" or "paint_plane" or "paint_depth" or "paint_symmetry" or "quality" or "custom_size")continue;result[key]=content(entry.Value,depth+1);}return result;}}if(value.VariantType==Variant.Type.Dictionary){var result=new Settings();foreach(var entry in value.AsGodotDictionary())result[entry.Key]=content(entry.Value,depth+1);return result;}return value;
    }
    private Resource? Resolve(Variant value)=>value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Resource r&&ActorDataOperations.ScriptIs(r,"res://scripts/actors/core/actor_object_reference.gd")?_animation.resolve_reference(r):null;
    public GArray dependencies(Resource actor){var result=new GArray();var values=actor.Get("values").AsGodotDictionary();var links=values.GetValueOrDefault("fog_motion_links",new Settings()).AsGodotDictionary();for(int i=0;i<4;i++)foreach(string kind in new[]{"source","velocity"}){var resource=Resolve(values.GetValueOrDefault($"fog_{kind}_{i}",default(Variant)));if(resource==null)continue;string id=resource.Get("values").AsGodotDictionary().GetValueOrDefault("source_actor","").AsString();id=links.GetValueOrDefault(id,id).AsString();if(id.Length>0)result.Add(id);}return result;}
    public void remap_actor(Resource actor,Settings ids,bool clearExternal){if(actor.Get("type_id").AsString()!="fog_volume")return;var values=actor.Get("values").AsGodotDictionary();var links=values.GetValueOrDefault("fog_motion_links",new Settings()).AsGodotDictionary().Duplicate();for(int i=0;i<4;i++)foreach(string kind in new[]{"source","velocity"}){var resource=Resolve(values.GetValueOrDefault($"fog_{kind}_{i}",default(Variant)));if(resource==null)continue;string original=resource.Get("values").AsGodotDictionary().GetValueOrDefault("source_actor","").AsString(),current=links.GetValueOrDefault(original,original).AsString();if(original.Length>0)links[original]=ids.GetValueOrDefault(current,clearExternal?"":current);}if(links.Count>0)values["fog_motion_links"]=links;}
}
